from collections import namedtuple


class RunResult(namedtuple('RunResult', ['stdout', 'stderr', 'status'])):

    __slots__ = ()

    def unic(self, out):
        try:
            return self._encode(unicode(out))
        # NameError for Python3 compatibility
        except (ValueError, TypeError, NameError):
            return out

    @staticmethod
    def _encode(x):
        return x.encode('utf-8')

    def __str__(self):
        return (' exit status:   {status}\n'
                ' stdout:\n {stdout}\n'
                ' stderr:\n {stderr}\n').format(
                    status=str(self.status),
                    stdout=self.unic(self.stdout),
                    stderr=self.unic(self.stderr))


class ClusterConnectionFailure(Exception):
    pass


class TimeoutError(Exception):
    pass


class ClusterObjectFailure(Exception):
    pass
